std::optional<std::string> account_box_answer(unsigned status, const std::string& body)
{
    if (status == 0 || status == 204 || status == 401 || status == 403)
        return std::nullopt;
    if (status != 200 || body.empty())
        throw std::runtime_error("The account box answered HTTP " + std::to_string(status) + ": " + body);
    return body;
}

std::optional<AccountDeletion> account_deletion(unsigned status)
{
    if (status == 204)
        return AccountDeletion::Deleted;
    if (status == 0)
        return AccountDeletion::NoAnswer;
    if (status == 401 || status == 403)
        return AccountDeletion::SignInEnded;
    return std::nullopt;
}

std::optional<std::string> model_list_fault(const ProviderProfile& profile, unsigned status, const std::string& body)
{
    const json response = json::parse(body, nullptr, false);
    const bool our_server_refused = profile.account_sign_in && status >= 400 && status != 401 && status != 403 && status != 426;
