// may send it inside the reply; Anthropic, by its words on a 400.
bool out_of_credits(unsigned status, const ServiceSays& says)
{
    return status == 402 || says.type == "insufficient_quota" || says.code == "credit_balance_exhausted" ||
           says.error_type == "payment_required" || starts_with(says.message, "Your credit balance is too low");
}

// The chat is more than the model takes: OpenAI's code, OpenRouter's
// error_type, Anthropic's words for the context window and for too many
// pictures in one chat.
bool too_long(unsigned status, const ServiceSays& says)
{
    return status == 413 || says.code == "context_length_exceeded" || says.error_type == "context_length_exceeded" ||
           starts_with(says.message, "prompt is too long") || says.message.find("many-image requests") != std::string::npos;
}

// Trouble of the service's own, which nobody here can fix: its 5xx and 408,
// and what each documents for it inside a reply (Anthropic's overloaded,
// api and timeout errors, OpenAI's server errors). OpenRouter's error_type
// decides wherever it is given, since its code collapses to server_error;
// its "unmapped" cannot be told, so it is not here.
bool service_trouble(unsigned status, const ServiceSays& says)
{
    static const std::set<std::string> openrouter{"server", "provider_unavailable", "provider_overloaded", "timeout"};
    if (!says.error_type.empty())
        return openrouter.count(says.error_type) > 0;
    return status >= 500 || status == 408 || says.type == "overloaded_error" || says.type == "api_error" ||
           says.type == "timeout_error" || says.type == "server_error" || says.type == "service_unavailable_error" ||
           says.code == "server_error" || says.code == "server_is_overloaded";
}

// A refusal the service explains to the person: their key, account, region,
// model access, content or limits. What OpenAI, Anthropic and OpenRouter
// document for 402, 403 and 429, OpenAI's and OpenRouter's 404 for a model
// the key cannot use, OpenAI's 400 for a service tier the person's project
// does not allow, and OpenRouter's kinds of refusal inside a reply.
// Anthropic's 404 names an endpoint or id the app sent, which is ours.
bool refused_the_person(unsigned status, const ServiceSays& says)
{
    static const std::set<std::string> openrouter{"permission_denied", "content_policy_violation", "refusal", "rate_limit_exceeded"};
    if (openrouter.count(says.error_type) > 0 || says.code == "rate_limit_exceeded")
        // numbers, in the app's language. The gateway always sends both.
        const json answer = json::parse(body, nullptr, false);
        if (!answer.is_object() || !answer.value("cost", json()).is_number_unsigned() || !answer.value("balance", json()).is_number_unsigned())
            return std::nullopt;
        const unsigned cost = answer["cost"].get<unsigned>();
        // TRN %1% is what the message costs in credits, %2% the credits the person has.
        return AgentError{"credits_exhausted",
                          Slic3r::format(translated_plural("This message needs %1% credit; you have %2%.",
                                                           "This message needs %1% credits; you have %2%.", cost),
                                         cost, answer["balance"].get<unsigned>()),
                          false};
    }
    // The person sent too many turns in a minute.
    if (code == "rate_limited")
        return rate_limited(name);
    if (code == "request_too_large")
        return too_large(name);
    return std::nullopt;
}

std::optional<AgentError> ProviderAgent::provider_answer(unsigned status, const json& answer) const
{
    const std::string& name = m_config.profile.display_name;
    const ServiceSays  says = service_says(answer);
    if (out_of_credits(status, says))
        return provider_out_of_credits(name);
    // Anthropic's 403 is a key without permission for what it asked; OpenAI's
    // and OpenRouter's 403s name other causes (a country, moderation, a key's
    // spending limit).
    if (status == 401 || (status == 403 && says.type == "permission_error"))
        // TRN %1% is an AI provider, such as OpenAI.
        return AgentError{"invalid_credentials", Slic3r::format(translated(L("The %1% API key was rejected. Update the AI configuration and try again.")), name), false};
    if (too_long(status, says))
        return too_large(name);
    if (says.message.empty())
        return status == 429 ? std::optional<AgentError>(rate_limited(name)) : std::nullopt;
    if (service_trouble(status, says))
        return service_said("provider_unavailable", name, says.message, true);
    if (refused_the_person(status, says)) {
        const bool too_many = status == 429 || says.code == "rate_limit_exceeded" || says.error_type == "rate_limit_exceeded";
        return service_said(too_many ? "rate_limited" : "provider_refused", name, says.message, too_many);
    }
    return std::nullopt;
}

std::optional<AgentError> ProviderAgent::in_reply_answer(const json& answer) const
{
    if (!m_config.profile.account_sign_in)
        return provider_answer(0, answer);
    // Inside a reply the gateway names one cause a person can act on: a chat
    // more than the model takes.
    const std::string code = service_says(answer).code;
    return code == "request_too_large" ? gateway_answer(code, answer.dump()) : std::nullopt;
}

