std::string read_file(const fs::path& path)
{
    std::ifstream in(path, std::ios::binary);
    require(in.is_open(), "cannot open " + path.string());
    std::ostringstream out;
    out << in.rdbuf();
    require(!in.bad(), "cannot read " + path.string());
    return out.str();
}

// pins.json at this build's format, empty when no version is pinned. Builds
// before it had a number wrote only the list, which is format 1's "versions".
json read_pins(const fs::path& file)
{
    json value = fs::exists(file) ? json::parse(read_file(file)) : json::array();
    if (value.is_array())
        value = json{{"schema", 1}, {"versions", std::move(value)}};
    read_format(kPinsFormat, value, "pinned versions");
    return value;
}

void sync_file(const fs::path& path)
{
#ifdef _WIN32
    HANDLE handle = CreateFileW(path.wstring().c_str(), GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                                nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
    require(handle != INVALID_HANDLE_VALUE, "cannot open for flush: " + path.string());
    const BOOL ok = FlushFileBuffers(handle);
    CloseHandle(handle);
    require(ok != 0, "cannot flush " + path.string());
#else
    const int fd = ::open(path.c_str(), O_RDONLY);
    require(fd >= 0, "cannot open for sync: " + path.string());
#ifdef __APPLE__
    const bool ok = ::fcntl(fd, F_FULLFSYNC) == 0 || ::fsync(fd) == 0;
#else
    const bool ok = ::fsync(fd) == 0;
#endif
    ::close(fd);
    require(ok, "cannot sync " + path.string());
#endif
}

