// would: with the system's error, as std::filesystem throws it.
class RefusedKeepingAgent final : public IAgentService
{
public:
    explicit RefusedKeepingAgent(std::errc refusal) : m_refusal(refusal) {}
    bool ready() const override { return true; }
    bool busy() const override { return false; }
    bool start(const AgentRequest&) override
    {
        throw std::filesystem::filesystem_error("in create_directories", std::filesystem::path("chats/c-1"),
                                                std::make_error_code(m_refusal));
    }
    bool continue_after_tool(const AgentToolResult&) override { return false; }
    void cancel() override {}
    std::optional<AgentEvent> poll() override { return std::nullopt; }

private:
    std::errc m_refusal;
};

} // namespace

TEST_CASE("a turn the system refuses to keep fails in the system's words, unreported", "[agent][errors]")
{
    for (const std::errc refusal : {std::errc::no_space_on_device, std::errc::permission_denied, std::errc::read_only_file_system}) {
        Harness harness(std::make_unique<RefusedKeepingAgent>(refusal));
        int reported = 0;
        harness.host.set_unexpected_error_handler([&reported](const std::string&, std::exception_ptr) { ++reported; });
        harness.handshake();
        harness.send_user_message("hello", "c-1");
        harness.pump_all();

        const json* failed = harness.last_of_type("assistant_failed");
        REQUIRE(failed != nullptr);
        CHECK((*failed)["payload"]["error"]["code"] == "storage_refused");
        CHECK((*failed)["payload"]["error"]["message"] ==
              std::string(system_name()) + " says: “" + std::make_error_code(refusal).message() + "”");
        CHECK((*failed)["payload"]["error"]["retryable"] == true);
        CHECK(harness.host.conversation().back().state == MessageState::Failed);
        CHECK_FALSE(harness.host.stream_active());
        CHECK(reported == 0);
    }
}

TEST_CASE("a turn whose keeping fails for another cause is reported unchanged", "[agent][errors]")
{
    Harness harness(std::make_unique<RefusedKeepingAgent>(std::errc::not_a_directory));
    harness.handshake();
    harness.send_user_message("hello", "c-1");
    CHECK_THROWS_AS(harness.pump_all(), std::filesystem::filesystem_error);
}

