// Writes down each dialog that reached the person while it lives, and closes
// it with Cancel, so a check that expects none fails instead of waiting on a
// modal nobody will press.
class ShownDialogs final : public Workspace::UnansweredDialogObserver
{
public:
    ShownDialogs() { Register(); }
    int Enter(wxDialog* dialog) override
    {
        titles.push_back(dialog->GetTitle().ToUTF8().data());
        std::cerr << "HARNESS DIALOG SHOWN '" << titles.back() << "'\n";
        return wxID_CANCEL;
    }
    std::vector<std::string> titles;
};

// Writes down each window that opens, as "title | text". With
// --dialog-witness the window is left for the witness to picture and close;
// without it, it is closed at once, as ShownDialogs does.
class SeenDialogs final : public Workspace::UnansweredDialogObserver
{
public:
    SeenDialogs() { Register(); }
    int Enter(wxDialog* dialog) override
    {
        const auto facts = Workspace::read_dialog(*dialog);
        shown.push_back(facts.title + " | " + facts.text);
        std::cerr << "HARNESS DIALOG SEEN '" << shown.back() << "'\n";
        return g_dialog_witness ? wxID_NONE : wxID_CANCEL;
    }
    std::vector<std::string> shown;
};

// Takes away this user's access to a folder and everything in it, as a
// permission change or a storage fault would, until destroyed. POSIX mode
// bits are not enforced on Windows, so there it denies read and write through
// the folder's ACL; the read denial matches icacls' "W", which includes
// SYNCHRONIZE and so blocks opening a file for reading as well.

