bool ShellController::checkpoint_unasked()
{
    // A pin that cannot be written is a failed save: the autosave keeps its
    // error, the title says "Couldn't save" and the next tick saves again.
    try {
        return m_agent_pane && m_agent_pane->web_view().host().checkpoint_active_chat();
    } catch (const std::runtime_error& error) {
        if (m_autosave->state() != Workspace::ProjectAutosave::State::Failed || m_autosave->error() != error.what())
            throw;
    }
    return false;
}

