// Takes away this user's access to a folder and everything in it, as a
// permission change or a storage fault would, until destroyed. POSIX mode
// bits are not enforced on Windows, so there it denies read and write through
// the folder's ACL; the read denial matches icacls' "W", which includes
// SYNCHRONIZE and so blocks opening a file for reading as well.
class UnavailableFolder
{
public:
    explicit UnavailableFolder(std::filesystem::path folder) : m_folder(std::move(folder))
    {
#ifdef _WIN32
        PACL original = nullptr;
        if (GetNamedSecurityInfoW(m_folder.c_str(), SE_FILE_OBJECT, DACL_SECURITY_INFORMATION, nullptr, nullptr,
                                  &original, nullptr, &m_descriptor) != ERROR_SUCCESS)
            throw std::runtime_error("cannot read the folder's access list: " + m_folder.string());
        m_original = original;
        EXPLICIT_ACCESSW deny{};
        BuildExplicitAccessWithNameW(&deny, const_cast<LPWSTR>(L"CURRENT_USER"),
                                     FILE_GENERIC_READ | FILE_GENERIC_WRITE | DELETE | FILE_DELETE_CHILD, DENY_ACCESS,
                                     SUB_CONTAINERS_AND_OBJECTS_INHERIT);
        PACL denied = nullptr;
        if (SetEntriesInAclW(1, &deny, original, &denied) != ERROR_SUCCESS)
            throw std::runtime_error("cannot build the denying access list");
        const DWORD applied = SetNamedSecurityInfoW(const_cast<LPWSTR>(m_folder.c_str()), SE_FILE_OBJECT,
                                                    DACL_SECURITY_INFORMATION, nullptr, nullptr, denied, nullptr);
        LocalFree(denied);
        if (applied != ERROR_SUCCESS)
            throw std::runtime_error("cannot deny access to " + m_folder.string());
#else
        m_original = std::filesystem::status(m_folder).permissions();
        std::filesystem::permissions(m_folder, std::filesystem::perms::none, std::filesystem::perm_options::replace);
#endif
    }

    ~UnavailableFolder()
    {
#ifdef _WIN32
        SetNamedSecurityInfoW(const_cast<LPWSTR>(m_folder.c_str()), SE_FILE_OBJECT, DACL_SECURITY_INFORMATION, nullptr,
                              nullptr, static_cast<PACL>(m_original), nullptr);
        LocalFree(m_descriptor);
#else
        std::filesystem::permissions(m_folder, m_original, std::filesystem::perm_options::replace);
#endif
#pragma once

// The operating system refusing to write a file for a cause the person can
// fix: the disk is full, or the folder is read-only or not theirs to write.
// Such a failure is the person's, so it reaches them in the system's own
// words and is not reported. Any other failure to write is unexpected.

#include <exception>
#include <optional>
#include <string>
#include <system_error>

#include "libslic3r/format.hpp"

#include "slic3r/GUI/JusPrin/Support/Translate.hpp"

namespace Slic3r::GUI::JusPrin {

// What a service or the system said, after its name, in the one form shown
// for another side's own words. The words stay in the language they came in.
inline std::string said_by(const std::string& name, const std::string& words)
{
    // TRN %1% is an AI provider or the operating system, such as OpenAI or macOS. %2% is what it answered, in its own words and language.
    return Slic3r::format(translated(L("%1% says: “%2%”")), name, words);
}

inline const char* system_name()
{
#if defined(__APPLE__)
    return "macOS";
#elif defined(_WIN32)
    return "Windows";
#else
    return "Linux";
#endif
}

// The system's words when it refused for one of those causes, or nothing.
// A std::filesystem error is a std::system_error, and so is what the app's
// own writes throw with the errno or Windows error they met.
inline std::optional<std::string> refused_by_system(const std::exception& error)
{
    const auto* system = dynamic_cast<const std::system_error*>(&error);
    if (system == nullptr)
        return std::nullopt;
    const std::error_condition condition = system->code().default_error_condition();
    if (condition != std::errc::no_space_on_device && condition != std::errc::permission_denied &&
        condition != std::errc::read_only_file_system && condition != std::errc::operation_not_permitted)
        return std::nullopt;
    return system->code().message();
}

} // namespace Slic3r::GUI::JusPrin

