#pragma once

#include "libslic3r/Model.hpp"

#include <nlohmann/json.hpp>

#include <cstdint>
#include <filesystem>
#include <functional>
#include <map>
#include <memory>
#include <set>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Workspace {

// The store owns immutable versions of an Orca project. Its caller captures
// on the GUI thread and runs publish() on one worker at a time. A new capture
// is allowed only after that worker has completed and its result is observed.
class ProjectVersionStore
    // The file the open project was opened from, kept with its MD5 from now
    // on, unless one is kept already. A .3mf is recorded on its own: it is
    // the project's file.
    void record_opened_from(const std::filesystem::path& source);
    bool open_managed_project(const std::string& project_id);
    // What to tell the person when open_managed_project failed.
    wxString open_failure() const;
    // open_managed_project failed because a newer JusPrin saved the project.
    bool open_refused_newer() const { return m_open_refused_newer; }
    bool export_copy(const std::filesystem::path& destination);

private:
    // OrcaSlicer's empty project, never saved: it stays in memory. A project
    // is saved once it holds a model, and stays saved from then on.

