void verify_autosave_fault()
{
    auto* autosave = installed_shell()->autosave();
    const std::string cube = std::string(JUSPRIN_SOURCE_DIR) + "/tests/data/test_stl/ASCII/20mmbox-LF.stl";
    check(m_plater->load_files(std::vector<boost::filesystem::path>{cube},
          LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence, false).size() == 1,
          "autosave_fault_model_loaded");
    check(autosave->save_now(), "autosave_fault_project_saved");
    const fs::path pending = fs::path(data_dir()) / "jusprin" / "projects" / persistence().document().project_id() / "pending";
    fs::remove_all(pending);
    std::ofstream(pending.string()) << "not a folder";
    const int reported_before = unexpected_errors_logged();
    // The report dialog, which the person answers.
    auto dialogs = std::make_shared<ShownDialogs>();
    check(m_plater->rename_object(0, "Edited before the fault"), "autosave_fault_edit_applied");
    // The report is logged and its dialog opens a moment after saving
    // stops: wait for all three.
    wait_until([autosave, reported_before, dialogs] {
                   return autosave->stopped() && unexpected_errors_logged() > reported_before && !dialogs->titles.empty();
               },
               "autosave_fault_stops_saving",
               [self = shared_from_this(), autosave, reported_before, dialogs] {
        self->check(autosave->state() == Workspace::ProjectAutosave::State::Failed && autosave->system_said().empty() &&
                        unexpected_errors_logged() == reported_before + 1 && dialogs->titles.size() == 1,
                    "autosave_fault_is_reported");
        installed_shell()->status_row()->show_overflow_menu();
        HeaderMenu* menu = self->visible_header_menu();
        const auto rows = header_menu_rows(menu);
        self->check(rows.size() > 2 && rows[1] == _L("Something went wrong on our side") && rows[2] == _L("Version history"),
                    "autosave_fault_menu_says_our_side");
        if (menu != nullptr)
            menu->close();
        const std::uint64_t attempts = autosave->capture_attempts();
        self->check(self->m_plater->rename_object(0, "Edited after the fault"), "autosave_fault_second_edit_applied");
        // Several of autosave's 2 s probes.
        const auto until = std::chrono::steady_clock::now() + std::chrono::seconds(6);
        self->wait_until([until] { return std::chrono::steady_clock::now() >= until; }, "autosave_fault_quiet_window",
                         [self, autosave, attempts, reported_before, dialogs] {
            self->check(autosave->capture_attempts() == attempts && autosave->stopped() &&
                            unexpected_errors_logged() == reported_before + 1 && dialogs->titles.size() == 1,
                        "autosave_fault_tries_no_more_and_reports_once");
            dialogs->Unregister();
            self->verify_deliberate_saves_after_fault(
                [self] { self->verify_sign_out_without_network([self] { self->finish(); }); });
        });
    });
}

