void AgentWebView::on_load_error(wxWebViewEvent& event)
{
    m_last_load_error = event.GetString();
    BOOST_LOG_TRIVIAL(error) << "JusPrin agent page failed to load: " << m_last_load_error.ToUTF8();
    show_bridge_error(_L("The AI page failed to load."));
}

void AgentWebView::on_handshake_deadline(wxTimerEvent&)
{
    if (!m_host->handshake_complete())
        show_bridge_error(_L("The AI page did not complete the bridge handshake."));
}

void AgentWebView::reload()
{
    hide_bridge_error();
    m_last_load_error.clear();
    if (m_webview != nullptr && !m_page_url.empty()) {
        m_host->reset_page();
        m_handshake_timer.StartOnce(kHandshakeDeadlineMs);
        WebView::LoadUrl(m_webview, m_page_url);
    } else {
        // Without a webview (missing bundle or creation failure) retry can
        // only re-check the packaged page.
        const boost::filesystem::path page = agent_page_path();
        if (boost::filesystem::exists(page))
            show_bridge_error(_L("Restart the application to load the AI page."));
        else
            show_bridge_error(_L("The packaged AI page is missing from this build."));
    }
}

void AgentWebView::set_error_fallback_actions(const wxString& return_label,
                                              const wxString& manual_label,
                                              std::function<void()> on_return,
                                              std::function<void()> on_manual)
{
    m_on_error_return = std::move(on_return);
    m_on_error_manual = std::move(on_manual);
    m_return_button->SetLabel(return_label);
    m_manual_button->SetLabel(manual_label);
    m_return_button->Show(static_cast<bool>(m_on_error_return));
    m_manual_button->Show(static_cast<bool>(m_on_error_manual));
    m_error_panel->Layout();
}

wxString AgentWebView::diagnostics_text(const wxString& reason) const
{
    wxString text = reason;
    text += "\n\n";
    text += _L("This is an internal connection between the application and its AI panel, not a network service.");
    text += "\n";
    text += wxString::Format("URL: %s", m_page_url.empty() ? wxString(agent_page_path().string()) : m_page_url);
    if (!m_last_load_error.empty())
        // TRN %1% is the web view's own error text.
        text += "\n" + format_wxstr(_L("Last load error: %1%"), m_last_load_error);
    // TRN The messages the app and its AI panel exchanged. %1% and %2% are counts.
    text += "\n" + format_wxstr(_L("Bridge traffic: %1% sent / %2% received"),
                                static_cast<unsigned long long>(m_host->messages_sent()),
                                static_cast<unsigned long long>(m_host->messages_received()));
    return text;
}

void AgentWebView::show_bridge_error(const wxString& reason)
{
    // The panel's own words, with the page's URL, its load error and the
    // traffic counts.
    BOOST_LOG_TRIVIAL(error) << "JusPrin AI page shows its connection error: " << diagnostics_text(reason).ToUTF8().data();
    m_error_detail->SetLabel(diagnostics_text(reason));
    m_error_detail->Wrap(std::max(FromDIP(160), GetClientSize().GetWidth() - FromDIP(32)));
    if (m_webview != nullptr)
        m_webview->Hide();
    m_error_panel->Show();
    Layout();
}

