WEB_LINK_FROM = re.compile(r'[a-z0-9_-]{1,32}')


@csrf_exempt
@require_POST
def web_link(request):
    """A link that opens one of the server's pages (JUSPRIN_V2_WEB_PAGES) signed
    in as the account whose token asks. JSON body: "page", the page's name, and
    "from", where in the app the click was, passed on to the page as ?from=. A
    page name the server doesn't know opens prices, so a newer app still gets a
    page from an older server. The link works once, for
    JUSPRIN_V2_WEB_LINK_SECONDS.

    A signed-out app sends no Authorization header and gets Credits and plans
    as a guest, whatever page it asked for; a token that is sent but wrong is
    still refused."""
    signed_out = 'HTTP_AUTHORIZATION' not in request.META
    user = None if signed_out else authenticate(request)
    if user is None and not signed_out:
        return _refuse('unauthorized', 401)
    try:
        body = json.loads(request.body or b'{}')
    except json.JSONDecodeError:
        return _refuse('invalid_request', 400)
    if not isinstance(body, dict):
        return _refuse('invalid_request', 400)
    page = body.get('page') if body.get('page') in settings.JUSPRIN_V2_WEB_PAGES else 'prices'
    origin = body.get('from')
    origin = origin if isinstance(origin, str) and WEB_LINK_FROM.fullmatch(origin) else None
    # The sheet's web view sends the computer's language, not the app's, so the
    # link carries the app's (jusprin.v2.language).
    language = {'lang': get_language()}
    if signed_out:
        query = urlencode({'guest': 1, **({'from': origin} if origin else {}), **language})
        response = JsonResponse({'url': request.build_absolute_uri(f"{settings.JUSPRIN_V2_WEB_PAGES['prices']}?{query}")})
        response['Cache-Control'] = 'no-store'
        return response
    token = secrets.token_urlsafe(32)
    cache.set(WEB_LINK_KEY.format(token), {'user_id': user.id, 'page': page, 'from': origin, **language},
              settings.JUSPRIN_V2_WEB_LINK_SECONDS)
    response = JsonResponse({'url': request.build_absolute_uri(reverse('jusprin_v2_web_open', args=[token]))})
    response['Cache-Control'] = 'no-store'
    return response


@require_GET
def web_open(request, token):
    """Where a link from web_link lands: signs the browser in as that account,
    replacing whoever it was signed in as, and goes on to the page."""
    key = WEB_LINK_KEY.format(token)
    link = cache.get(key)
    # Only the request whose delete removes the entry signs in, so a link
    # opened twice at once still works once.
    user = User.objects.filter(id=link['user_id'], is_active=True).first() if link and cache.delete(key) else None
    if user is None:
        return render(request, 'jusprin/v2/sign_in_result.html', {
            'heading': _('This link has expired'),
            'line': _('Go back to JusPrin and open the page again.'),
        }, status=410)
    login(request, user, backend='app.accounts.SyndicateSpecificBackend')
    path = settings.JUSPRIN_V2_WEB_PAGES[link['page']]
    response = HttpResponseRedirect(f"{path}?{urlencode({'from': link['from']})}" if link['from'] else path)
    # A link made before the app said its language has none.
    if link.get('lang'):
        keep_language(request, response, link['lang'])
    return response


# Where the server's pages end: a checkout, a plan change, a cancel. The app
# watches its sheet for this address, closes the sheet and reads the account
# again; in a browser, the person reads this.
@require_GET
def web_done(request):
    return render(request, 'jusprin/v2/sign_in_result.html', {
        'heading': _("You're all set"),
        'line': _('You can close this tab and go back to JusPrin.'),
    })


def _refuse(code: str, status: int) -> HttpResponse:
    return HttpResponse(error_body(code), status=status, content_type='application/json')


def server_error(request):
    """The site's answer when a view fails unexpectedly (urls_ent.handler500),
    after Sentry's Django integration has reported the failure. On JusPrin 2's
    pages the person reads the one sentence for it, in the app's language; the
    endpoints the app calls answer with the gateway's error body. Every other
    path keeps Django's own page."""
    if not request.path.startswith(PATH):
        return defaults.server_error(request)
    if request.path.startswith(PAGES):
        heading = _('Something went wrong on our side')
        return render(request, 'jusprin/v2/web/message.html', {'title': heading, 'heading': heading}, status=500)
    return HttpResponse(unexpected_body(), status=500, content_type='application/json')
from django.conf import settings
from oauth2_provider.oauth2_backends import get_oauthlib_core
from rest_framework.permissions import SAFE_METHODS


def authenticate(request):
    """The active user whose OAuth2 bearer token the request carries, or None.

    Only a token issued to the JusPrin 2 app counts; another app's token is
    treated as no token at all, so it cannot reach the account or its credits.
    The token needs `read` to read and `write` for anything else, the same rule
    ScopedOAuth2Authentication (obico-server's api/authentication.py) applies
    to the API for apps. A deactivated account's token is refused, and so is a
    token issued to no user.
    """
    scopes = ['read'] if request.method in SAFE_METHODS else ['write']
    valid, oauthlib_request = get_oauthlib_core().verify_request(request, scopes=scopes)
    if not valid or oauthlib_request.access_token.application.client_id != settings.JUSPRIN_V2_OAUTH_CLIENT_ID:
        return None
    user = oauthlib_request.user
    if user is None or not user.is_active:
        return None
    return user

