@csrf_exempt
@require_POST
def cb_webhook(request):
    """Chargebee's webhook for JusPrin 2's own site. The post is trusted only
    for the event's id: the event is read back from that site, so a forged
    post changes nothing."""
    try:
        event_id = json.loads(request.body).get('id')
    except (ValueError, AttributeError):
        event_id = None
    cb_event = billing.retrieve_event(event_id) if isinstance(event_id, str) and event_id else None
    if cb_event is None:
        return HttpResponse(status=400)
    billing.handle_event(cb_event)
    return HttpResponse('')


@require_GET
def account_box(request):
    """The box near the top of the app's Account page: a piece of HTML, or
    nothing (204), which shows no box. The app asks with the person's token when
    they are signed in and with none when they are not. It shows the HTML in a
    frame that runs no scripts, so the box is words and pictures only and
def handle_event(cb_event: Dict) -> None:
    """A webhook event from JusPrin 2's site; one about anything but a JusPrin 2
    plan or credit pack changes nothing."""
    content = cb_event.get('content') or {}
    event_type = cb_event.get('event_type')
    if content.get('subscription') and event_type in SUBSCRIPTION_EVENTS | INVOICE_EVENTS:
        user = user_for_customer(content['subscription'].get('customer_id'))
        if user is None:
            return
        # Chargebee may send events late, twice or out of order, so the
        # subscription is read as it is now, not as the event saw it.
        sub = chargebee.Subscription.retrieve(content['subscription']['id'], env=_site()).subscription.values
        # Only JusPrin 2 sells on its site: a plan this server does not know
        # is one it was never told about, and its credits would never come.
        if not is_v2_plan(plan_price_id(sub)):
            raise RuntimeError(f"Chargebee subscription {sub.get('id')} of customer {sub.get('customer_id')} is on plan "
                               f"{plan_price_id(sub)!r}, which JUSPRIN_V2_PLANS does not hold")
        record_subscription(user, sub)
    elif event_type in INVOICE_EVENTS:
        invoice = content.get('invoice') or {}
        user = user_for_customer(invoice.get('customer_id'))
        if user is not None and not invoice.get('subscription_id'):
            record_pack_invoice(user, invoice)
