class CrossSiteReadTestCase(TestCase):
    # Which other sites a browser lets read these answers, with the visitor's cookies

    def get(self, path, origin, method='get'):
        headers = {'HTTP_ORIGIN': origin}
        if method == 'options':
            headers['HTTP_ACCESS_CONTROL_REQUEST_METHOD'] = 'GET'
        response = getattr(Client(), method)(path, **headers)
        return response.headers.get('Access-Control-Allow-Origin'), response.headers.get('Access-Control-Allow-Credentials')

    def test_www_obico_io_reads_subscriptions_with_cookies(self, _):
        for method in ('get', 'options'):
            self.assertEqual(self.get('/ent/api/subscriptions/', 'https://www.obico.io', method), ('https://www.obico.io', 'true'), method)

    def test_any_site_reads_stats_without_cookies(self, _):
        for origin in ('https://www.obico.io', 'https://docs.example'):
            for method in ('get', 'options'):
                self.assertEqual(self.get('/ent/api/pub_stats/', origin, method), ('*', None), (origin, method))

    def test_stats_carry_no_account(self, _):
        client = Client()
        client.force_login(User.objects.create(email='stats@example.com'))
        self.assertEqual(client.get('/ent/api/pub_stats/').json(), {'print_num': 1})

    def test_other_sites_are_not_allowed(self, _):
        for origin in ('https://attacker.example', 'https://obico.io.attacker.example', 'http://www.obico.io'):
            for path in ('/ent/api/subscriptions/', '/ent/partners/api/elegoo/x/'):
                for method in ('get', 'options'):
                    self.assertEqual(self.get(path, origin, method), (None, None), (origin, path, method))

    def test_the_elegoo_partner_api_has_no_cross_site_rule(self, _):
        self.assertEqual(self.get('/ent/partners/api/elegoo/x/', 'https://www.obico.io'), (None, None))
