    void verify_autosave_fault_after_cleanup()
    {
        auto* autosave = installed_shell()->autosave();
        const fs::path pending = fs::path(data_dir()) / "jusprin" / "projects" / persistence().document().project_id() / "pending";
        fs::remove_all(pending);
        std::ofstream(pending.string()) << "not a folder";
        const int reported_before = unexpected_errors_logged();
        // The report dialog, which the person answers.
        auto dialogs = std::make_shared<ShownDialogs>();
        check(m_plater->rename_object(0, "Edited before the fault"), "autosave_fault_edit_applied");
        // The report is logged and its dialog opens a moment after saving
        // stops: wait for all three.
        wait_until([autosave, reported_before, dialogs] {
                       return autosave->stopped() && unexpected_errors_logged() > reported_before && !dialogs->titles.empty();
                   },
                   "autosave_fault_stops_saving",
                   [self = shared_from_this(), autosave, reported_before, dialogs] {
            self->check(autosave->state() == Workspace::ProjectAutosave::State::Failed && autosave->system_said().empty() &&
                            unexpected_errors_logged() == reported_before + 1 && dialogs->titles.size() == 1,
                        "autosave_fault_is_reported");
