#pragma once

// The operating system refusing to write a file for a cause the person can
// fix: the disk is full, or the folder is read-only or not theirs to write.
// Such a failure is the person's, so it reaches them in the system's own
// words and is not reported. Any other failure to write is unexpected.

#include <exception>
#include <optional>
#include <string>
#include <system_error>

#include <boost/system/error_code.hpp>
#include <boost/system/system_error.hpp>

#include "libslic3r/format.hpp"

#include "slic3r/GUI/JusPrin/Support/Translate.hpp"

namespace Slic3r::GUI::JusPrin {

// What a service or the system said, after its name, in the one form shown
// for another side's own words. The words stay in the language they came in.
inline std::string said_by(const std::string& name, const std::string& words)
{
    // TRN %1% is an AI provider or the operating system, such as OpenAI or macOS. %2% is what it answered, in its own words and language.
    return Slic3r::format(translated(L("%1% says: “%2%”")), name, words);
}

inline const char* system_name()
{
#if defined(__APPLE__)
    return "macOS";
#elif defined(_WIN32)
    return "Windows";
#else
    return "Linux";
#endif
}

// The system's words when it refused for one of those causes, or nothing.
// A std::filesystem error is a std::system_error, and so is what the app's
// own writes throw with the errno or Windows error they met. OrcaSlicer's own
// file code throws boost::filesystem errors, which are boost's system_error.
inline std::optional<std::string> refused_by_system(const std::exception& error)
{
    if (const auto* system = dynamic_cast<const std::system_error*>(&error)) {
        const std::error_condition condition = system->code().default_error_condition();
        if (condition != std::errc::no_space_on_device && condition != std::errc::permission_denied &&
            condition != std::errc::read_only_file_system && condition != std::errc::operation_not_permitted)
            return std::nullopt;
        return system->code().message();
    }
    if (const auto* system = dynamic_cast<const boost::system::system_error*>(&error)) {
        namespace errc = boost::system::errc;
        const boost::system::error_condition condition = system->code().default_error_condition();
        if (condition != errc::no_space_on_device && condition != errc::permission_denied &&
            condition != errc::read_only_file_system && condition != errc::operation_not_permitted)
            return std::nullopt;
        return system->code().message();
    }
    return std::nullopt;
}

} // namespace Slic3r::GUI::JusPrin
