// A file the export could not write: OrcaSlicer's writers say only that they
// failed, and the errno their file calls left is the system's reason, when it
// gave one. A refusal the person can fix, such as a full disk or a folder they
// cannot write, is theirs and says so in the system's words.
CommandResult unwritten(const std::string& message, int error = errno)
{
    CommandResult failed = CommandResult::failure(WorkspaceError::Failed, message);
    if (error != 0) {
        const std::system_error cause(error, std::generic_category());
        if (const std::optional<std::string> words = refused_by_system(cause)) {
