            if (const int error = errno; error != 0)
                throw std::system_error(error, std::generic_category(), exported.message);
            throw std::runtime_error(exported.message);
        }
        ProjectVersionStore::publish_export_archive(temporary, destination);
        return true;
    } catch (...) {
        std::error_code ignored;
        std::filesystem::remove(temporary, ignored);
        throw;
    }
}

