bool ShellController::save_before_dropping_changes()
{
    if (m_autosave && m_autosave->save_now())
        return true;
    // A refusal the person can fix is theirs: the project's "Couldn't save"
    // line already names it in the system's words, and the caller says what
    // did not happen because of it.
    if (m_autosave && !m_autosave->system_said().empty())
        return false;
    report_unexpected_error("saving a version of the project before dropping setting changes",
                            m_autosave ? m_autosave->error() : "the project has no version history");
    return false;
}

