3952:    void verify_unavailable_project_storage()
        // like any other unavailable project, not the whole list.
        const auto listed = installed_shell()->home_view()->backend().recent_projects();
        check(listed.problem.empty() &&
                  std::none_of(listed.projects.begin(), listed.projects.end(),
                               [id = persistence().document().project_id()](const auto& project) { return project.id == id; }),
              "unavailable_storage_home_leaves_out_the_unreadable_project");
        check(m_plater->rename_object(0, "Edited while unavailable"), "unavailable_storage_edit_applied");
        // With the edit unsaved, the saves the app makes on purpose meet the
        // same refusal and treat it the same way: what was asked does not
        // happen, the person is told in the system's words, and nothing
        // reaches us.
        const int deliberate_reports_before = unexpected_errors_logged();
        auto seen = std::make_shared<SeenDialogs>();
        check(m_plater->new_project(true, true, "Next") == wxID_CANCEL && m_plater->model().objects.size() == 1,
              "unavailable_storage_new_project_keeps_the_open_one");
        installed_shell()->left_pane()->set_restore_confirmation([] { return true; });
        installed_shell()->left_pane()->restore_version(saved.front().id);
        installed_shell()->left_pane()->set_restore_confirmation({});
        bool export_refused = false;
        try {
            if (!autosave->export_copy(std::filesystem::path(data_dir()) / "unavailable-export.3mf"))
                autosave->throw_failure();
        } catch (const std::exception& error) {
            export_refused = Slic3r::GUI::JusPrin::refused_by_system(error).has_value();
        }
        check(export_refused, "unavailable_storage_export_keeps_the_systems_refusal");
        const std::string new_chat = nlohmann::json{{"protocol", Agent::Protocol::kName}, {"version", Agent::Protocol::kVersion},
                                                    {"id", "unavailable-new-chat"}, {"type", "create_conversation"},
                                                    {"payload", nlohmann::json::object()}}.dump();
        run_in_chat("window.wx.postMessage(" + nlohmann::json(new_chat).dump() + ")");
        // Long enough for several of autosave's 2 s retries.
        const auto until = std::chrono::steady_clock::now() + std::chrono::seconds(8);
        auto saved_while_unavailable = std::make_shared<bool>(false);
        const int reported_before = unexpected_errors_logged();
        wait_until([until] { return std::chrono::steady_clock::now() >= until; }, "unavailable_storage_retry_window",
                   [self = shared_from_this(), autosave, folder, saved, saved_head, saved_while_unavailable, ids, reported_before,
                    deliberate_reports_before, seen]() mutable {
            self->check(!*saved_while_unavailable && autosave->state() == Workspace::ProjectAutosave::State::Failed &&
                            autosave->current_version() == saved_head,
                        "unavailable_storage_edit_stays_unsaved_and_reported");
            self->check(installed_shell()->status_row()->project_summary().BeforeFirst('\n').EndsWith(
                            wxGetTranslation("Couldn't save")),
                        "unavailable_storage_has_plain_status_text");
            // A folder the person cannot write is theirs to fix: the system's
            // words reach them, and nothing reaches us.
            const std::string system_said = autosave->system_said();
            self->check(!autosave->stopped() && system_said.rfind(Slic3r::GUI::JusPrin::system_name(), 0) == 0 &&
                            system_said.find("“") != std::string::npos,
                        "unavailable_storage_keeps_the_systems_words");
            self->check(unexpected_errors_logged() == reported_before, "unavailable_storage_reports_nothing");
            const auto shown = [&seen](const wxString& title, const wxString& text) {
                const std::string line = std::string(title.ToUTF8().data()) + " | " + text.ToUTF8().data();
                return std::find(seen->shown.begin(), seen->shown.end(), line) != seen->shown.end();
            };
            const wxString said = wxString::FromUTF8(system_said);
            self->check(shown(_L("Restore failed"), _L("This version couldn't be restored. Try again.") + "\n\n" + said),
                        "unavailable_storage_restore_shows_the_systems_words");
            self->check(shown(_L("Couldn't save"), said), "unavailable_storage_new_chat_shows_the_systems_words");
            self->check(unexpected_errors_logged() == deliberate_reports_before,
                        "unavailable_storage_deliberate_saves_report_nothing");
            for (const std::string& line : seen->shown)
                std::cerr << "HARNESS NOTE unavailable storage showed '" << line << "'\n";
            // The overflow menu says so too, directly under the name row,
            // with the system's words under it.
            installed_shell()->status_row()->show_overflow_menu();
            HeaderMenu* menu = self->visible_header_menu();
            const wxString retry = _L("Changes couldn't be saved. JusPrin will retry.");
            const auto rows = header_menu_rows(menu);
            auto* retry_row = menu ? wxWindow::FindWindowByName(retry, menu) : nullptr;
            self->check(rows.size() > 3 && rows[0] == overflow_project_name() && rows[1] == retry &&
                            rows[2] == wxString::FromUTF8(system_said) && rows[3] == _L("Version history") &&
                            retry_row != nullptr && !retry_row->IsEnabled(),
                        "unavailable_storage_menu_says_it_will_retry_under_the_name");
            if (menu != nullptr)
                menu->close();
            installed_shell()->agent_pane()->web_view().host().refresh_page_state();
            self->check(ids(autosave->history()) == ids(saved), "unavailable_storage_version_list_survives_retries");
            folder.reset();
            self->wait_until([autosave, saved_head] {
                return autosave->state() == Workspace::ProjectAutosave::State::Saved &&
                       autosave->current_version() != saved_head;
            }, "unavailable_storage_saving_resumes_by_itself", [self, autosave, saved] {
                const auto history = autosave->history();
                self->check(history.size() == saved.size() + 1 && history.back().id == autosave->current_version() &&
                                self->m_plater->model().objects[0]->name == "Edited while unavailable",
                            "unavailable_storage_edit_saved_after_recovery");
                self->check(installed_shell()->status_row()->project_summary().BeforeFirst('\n').EndsWith(
                                wxGetTranslation("Saved")),
                            "unavailable_storage_status_returns_to_saved");
                self->verify_unavailable_projects_folder();
            });
        }, [autosave, saved_while_unavailable] {
            *saved_while_unavailable |= autosave->state() == Workspace::ProjectAutosave::State::Saved;
        });
    }

    // A save fails for a cause that is ours, not the person's: a file stands
    // where the project's folder for unfinished versions belongs, which no
    // code of the app makes. The failure goes to the report once, the project
    // stops saving for this run, and its menu says the fault is on our side.

