            // and a folder that refused it cannot be told apart, so it is ours.
            const std::string rollback_error = restore_profiles(plater, before);
            throw std::runtime_error("The printer profiles could not be installed." +
                                     (rollback_error.empty() ? std::string() : " " + rollback_error));
        }
        if (wxGetApp().mainframe) wxGetApp().mainframe->update_side_preset_ui();
        return true;
    } catch (const std::exception& exception) {
        const std::string rollback_error = restore_profiles(plater, before);
        error = std::string("The printer profiles could not be loaded: ") + exception.what();
        if (!rollback_error.empty()) error += " " + rollback_error;
        // The data folder refused by the system, as on a full disk: the
        // person's. Anything else is ours.
        if (!refused_by_system(exception))
            throw std::runtime_error(error);
        return false;
    }
