void show_open_failure(wxWindow* parent, const Workspace::ProjectAutosave& autosave)
{
    const bool newer = autosave.open_refused_newer();
    // The person's: a newer JusPrin saved it, another JusPrin holds it, or
    // the system refused to save the open one, in its words. Any other
    // failure is ours, and goes up to the entry point's report.
    if (!newer && !autosave.open_elsewhere() && autosave.system_said().empty())
        autosave.throw_failure();
    MessageDialog dialog(parent, Workspace::with_system_said(autosave.open_failure(), autosave.system_said()), _L("Couldn't open project"),
                         wxICON_ERROR | (newer ? wxYES_NO : wxOK));
    if (newer) {
        dialog.SetButtonLabel(wxID_YES, _L("Get the new version…"), true);
        dialog.SetButtonLabel(wxID_NO, _L("Close"));
// -- a project saved, a print started -- so it is refreshed on the way in
// rather than kept live behind the canvas. While it is on screen its printer
// cards stay live (HomeWebView::set_live).
// The JusPrin view shows Home, Prepare and the project page. A switch of the
// main window to any other of OrcaSlicer's pages is refused, whatever asked
// for it: Ctrl+Tab, a "Go to" key, MainFrame::jump_to_monitor after a send.
// OrcaSlicer's own Ctrl+Tab already steps over a page that refuses.
bool ShellController::checkpoint_unasked()
{
    // A pin that cannot be written is a failed save: the autosave keeps its
    // error, the title says "Couldn't save" and the next tick saves again.
    try {
        return m_agent_pane && m_agent_pane->web_view().host().checkpoint_active_chat();
    } catch (const std::runtime_error& error) {
        if (m_autosave->state() != Workspace::ProjectAutosave::State::Failed || m_autosave->error() != error.what())
            throw;
    }
    return false;
}

