    void verify_profiles_that_cannot_be_installed()
    {
        const fs::path system = fs::path(data_dir()) / "system";
        fs::create_directories(system);
        std::string problem;
        std::string thrown;
        bool        installed = false;
        {
            UnavailableFolder locked(system.string());
            try {
                installed = SetupCommands::install_printer_profiles(*m_plater, {{"Creality", "Creality K1C", "0.4", ""}}, problem);
            } catch (const std::exception& error) {
                thrown = error.what();
            }
        }
        // The folder refused: the person's, with the system's reason, not thrown.
        check(!installed && thrown.empty() && problem.find("Permission denied") != std::string::npos,
              "orca_import_profiles_the_system_refuses_are_the_persons");
        // A vendor the app's own profiles do not hold, as a broken install
        // leaves one: ours, thrown.
        thrown.clear();
        try {
            installed = SetupCommands::install_printer_profiles(*m_plater, {{"NoSuchVendor", "No Such Printer", "0.4", ""}}, problem);
        } catch (const std::exception& error) {
            thrown = error.what();
        }
        check(!installed && !thrown.empty(), "orca_import_profiles_that_cannot_be_installed_are_ours");
    }
