TEST_CASE("a refusal is the system's in std and in boost's errors alike, and nothing else is", "[agent][errors]")
{
    using Slic3r::GUI::JusPrin::refused_by_system;
    const std::string denied = std::make_error_code(std::errc::permission_denied).message();
    CHECK(refused_by_system(std::system_error(std::make_error_code(std::errc::permission_denied))) == denied);
    CHECK(refused_by_system(boost::filesystem::filesystem_error(
              "status", boost::system::errc::make_error_code(boost::system::errc::permission_denied))) == denied);
    CHECK(refused_by_system(boost::filesystem::filesystem_error(
              "status", boost::system::errc::make_error_code(boost::system::errc::no_space_on_device))).has_value());
    CHECK_FALSE(refused_by_system(boost::filesystem::filesystem_error(
                    "status", boost::system::errc::make_error_code(boost::system::errc::no_such_file_or_directory))).has_value());
    CHECK_FALSE(refused_by_system(std::runtime_error("Permission denied")).has_value());
}

