TEST_CASE("a refusal is the person's only where their storage is used, whatever the system's reason", "[agent][errors]")
{
    using namespace Slic3r::GUI::JusPrin;
    const std::filesystem::path folder = std::filesystem::path("projects");
    // A system error is nobody's by its number alone.
    CHECK_FALSE(refused_by_system(std::system_error(std::make_error_code(std::errc::permission_denied))).has_value());
    CHECK_FALSE(refused_by_system(boost::filesystem::filesystem_error(
                    "status", boost::system::errc::make_error_code(boost::system::errc::no_space_on_device))).has_value());
    CHECK_FALSE(refused_by_system(std::runtime_error("Permission denied")).has_value());
    // In the person's storage, any reason the system gives is theirs, with
    // the folder: a full disk, a quota, a failing or unplugged drive, a file
    // too large for the disk.
    for (const int reason : {ENOSPC, EDQUOT, EIO, ENOENT, EFBIG, EACCES, EROFS}) {
        const std::error_code code(reason, std::generic_category());
        std::optional<std::string> words;
        try {
            persons_storage(folder, [&] { throw std::filesystem::filesystem_error("write", folder / "a", code); });
        } catch (const std::exception& error) {
            words = refused_by_system(error);
        }
        CHECK(words == folder.u8string() + ": " + code.message());
    }
    // Boost's errors, as OrcaSlicer's file code throws them, alike.
    std::optional<std::string> boost_words;
    try {
        persons_storage(folder, [] {
            throw boost::filesystem::filesystem_error("status", boost::system::errc::make_error_code(boost::system::errc::io_error));
        });
    } catch (const std::exception& error) {
        boost_words = refused_by_system(error);
    }
    CHECK(boost_words.has_value());
    // A failure that is not the system's goes through unchanged.
    CHECK_THROWS_AS(persons_storage(folder, [] { throw std::logic_error("ours"); }), std::logic_error);
}

#ifndef _WIN32
TEST_CASE("a turn the system refuses to keep fails in the system's words, with the folder, unreported", "[agent][errors]")
{
    Harness harness(std::make_unique<KeepingAgent>(true));
    int reported = 0;
    harness.host.set_unexpected_error_handler([&reported](const std::string&, std::exception_ptr) { ++reported; });
    harness.handshake();
    const std::filesystem::path folder = std::filesystem::path(harness.workspace.auxiliary_data_dir()) / "JusPrin";
    std::filesystem::create_directories(folder);
    std::filesystem::permissions(folder, std::filesystem::perms::owner_read | std::filesystem::perms::owner_exec,
                                 std::filesystem::perm_options::replace);
    harness.send_user_message("hello", "c-1");
    harness.pump_all();
    std::filesystem::permissions(folder, std::filesystem::perms::owner_all, std::filesystem::perm_options::replace);

    const json* failed = harness.last_of_type("assistant_failed");
    REQUIRE(failed != nullptr);
    CHECK((*failed)["payload"]["error"]["code"] == "storage_refused");
    CHECK((*failed)["payload"]["error"]["message"] == std::string(system_name()) + " says: “" + folder.u8string() + ": " +
                                                          std::make_error_code(std::errc::permission_denied).message() + "”");
    CHECK((*failed)["payload"]["error"]["retryable"] == true);
    CHECK(harness.host.conversation().back().state == MessageState::Failed);
    CHECK(reported == 0);
}
#endif

TEST_CASE("a system error from outside the person's storage is ours, whatever its reason", "[agent][errors]")
{
    Harness harness(std::make_unique<KeepingAgent>(false));
    harness.handshake();
    // The turn starts as the message is sent.
    CHECK_THROWS_AS(harness.send_user_message("hello", "c-1"), std::filesystem::filesystem_error);
}

