// pictures in one chat.
bool too_long(unsigned status, const ServiceSays& says)
{
    return status == 413 || says.code == "context_length_exceeded" || says.error_type == "context_length_exceeded" ||
           starts_with(says.message, "prompt is too long") || says.message.find("many-image requests") != std::string::npos;
}

// Trouble of the service's own, which nobody here can fix: its 5xx and 408,
// and what each documents for it inside a reply (Anthropic's overloaded,
// api and timeout errors, OpenAI's server errors). OpenRouter's error_type
// decides wherever it is given, since its code collapses to server_error;
// its "unmapped" cannot be told, so it is not here.
bool service_trouble(unsigned status, const ServiceSays& says)
{
    static const std::set<std::string> openrouter{"server", "provider_unavailable", "provider_overloaded", "timeout"};
    if (!says.error_type.empty())
        return openrouter.count(says.error_type) > 0;
    return status >= 500 || status == 408 || says.type == "overloaded_error" || says.type == "api_error" ||
           says.type == "timeout_error" || says.type == "server_error" || says.type == "service_unavailable_error" ||
           says.code == "server_error" || says.code == "server_is_overloaded";
}

// A refusal the service explains to the person: their key, account, region,
// model access, content or limits. What OpenAI, Anthropic and OpenRouter
// document for 402, 403 and 429, OpenAI's and OpenRouter's 404 for a model
// the key cannot use, OpenAI's 400 for a service tier the person's project
// does not allow, and OpenRouter's kinds of refusal inside a reply.
// Anthropic's 404 names an endpoint or id the app sent, which is ours.
bool refused_the_person(unsigned status, const ServiceSays& says)
{
    static const std::set<std::string> openrouter{"permission_denied", "content_policy_violation", "refusal", "rate_limit_exceeded"};
    if (openrouter.count(says.error_type) > 0 || says.code == "rate_limit_exceeded")
        return true;
    if (status == 404)
        return says.type != "not_found_error";
    return status == 402 || status == 403 || status == 429 || (status == 400 && says.param == "service_tier");
}

// What the service said, after its name, for a cause it explains itself.
AgentError service_said(const char* code, const std::string& name, const std::string& words, bool retryable)
{
    return {code, said_by(name, words), retryable};
}

AgentError provider_out_of_credits(const std::string& name)
