    if (says.message.empty())
        return status == 429 ? std::optional<AgentError>(rate_limited(name)) : std::nullopt;
    if (service_trouble(status, says))
        return service_said("provider_unavailable", name, says.message, true);
    if (refused_the_person(status, says)) {
        const bool too_many = status == 429 || says.code == "rate_limit_exceeded" || says.error_type == "rate_limit_exceeded";
        return service_said(too_many ? "rate_limited" : "provider_refused", name, says.message, too_many);
    }
    return std::nullopt;
}

