    // A refusal of what the app sent, and answers with no words of the
    // service's: whose they are cannot be told, so they are ours.
    const std::string refused = R"({"error":{"message":"Unknown parameter: 'input[0].foo'.","type":"invalid_request_error","code":"unknown_parameter"}})";
    struct Case { unsigned status; std::string body; const char* names; };
    const Case cases[] = {{400u, refused, "unknown_parameter"}, {500u, "<html>busy</html>", "<html>busy</html>"},
                          {503u, "", "503"}, {529u, R"({"error":{"type":"overloaded_error"}})", "overloaded_error"}};
    for (const Case& item : cases) {
        const unsigned status = item.status;
        CAPTURE(status);
        Harness h;
        REQUIRE(h.agent->start(request_fixture()));
        h.fake->refuse(status, item.body);
        CHECK_THROWS_WITH(h.poll_until(AgentEventKind::Failed),
                          ContainsSubstring("Test Provider answered HTTP " + std::to_string(status)) &&
                              ContainsSubstring(item.names) && ContainsSubstring("assistant-7-attempt-1"));
        // The turn stopped there: nothing is waiting, nothing more arrives.
        CHECK_FALSE(h.agent->busy());
        CHECK(h.fake->cancelled);
        CHECK_FALSE(h.agent->poll());
    }
}

