TEST_CASE("a refusal the service explains, or its own trouble, is shown in its words after its name", "[agent][openai][errors]")
{
    struct Case { const char* provider; unsigned status; std::string body; const char* code; bool retryable; std::string message; };
    const Case cases[] = {
        // developers.openai.com/api/docs/guides/error-codes: 403 for a country.
        {"openai", 403, R"({"error":{"code":"unsupported_country_region_territory","message":"Country, region, or territory not supported","param":null,"type":"request_forbidden"}})",
         "provider_refused", false, "OpenAI says: “Country, region, or territory not supported”"},
        // Production, Sentry JUSPRIN-APP-E: a workspace that serves only the person's own provider keys.
        {"openrouter", 404, R"({"error":{"message":"No endpoints found that can be served by your own provider keys. This workspace is restricted to BYOK capacity. Add provider keys at https://openrouter.ai/workspaces/default/byok","code":404,"metadata":{}}})",
         "provider_refused", false, "OpenRouter says: “No endpoints found that can be served by your own provider keys. This workspace is restricted to BYOK capacity. Add provider keys at https://openrouter.ai/workspaces/default/byok”"},
        // A 429 whose words name a cap, not a moment to wait.
        {"openrouter", 429, R"({"error":{"code":429,"message":"Rate limit exceeded: free-models-per-day."}})",
         "rate_limited", true, "OpenRouter says: “Rate limit exceeded: free-models-per-day.”"},
        // OpenAI's 400 for a service tier the person's project does not allow.
        {"openai", 400, R"({"error":{"message":"Invalid service_tier argument: The requested service tier is not allowed for this project.","type":"invalid_request_error","param":"service_tier","code":null}})",
         "provider_refused", false, "OpenAI says: “Invalid service_tier argument: The requested service tier is not allowed for this project.”"},
        // The service's own trouble: OpenAI's 503, OpenRouter's 502.
        {"openai", 503, R"({"error":{"message":"The requested model is temporarily overloaded.","type":"service_unavailable_error","code":"server_is_overloaded"}})",
         "provider_unavailable", true, "OpenAI says: “The requested model is temporarily overloaded.”"},
        {"openrouter", 502, R"({"error":{"code":502,"message":"Your chosen model is down or we received an invalid response from it","metadata":{"error_type":"provider_unavailable"}}})",
         "provider_unavailable", true, "OpenRouter says: “Your chosen model is down or we received an invalid response from it”"},
        // docs.claude.com/en/api/errors: 529 overloaded.
        {"anthropic", 529, R"({"type":"error","error":{"type":"overloaded_error","message":"Overloaded"},"request_id":"req_1"})",
         "provider_unavailable", true, "Anthropic says: “Overloaded”"},
    };
    for (const Case& item : cases) {
        CAPTURE(item.provider, item.status);
        Responses r(item.provider);
        r.fake->refuse(item.status, item.body);
        const auto error = r.failure();
        REQUIRE(error);
        CHECK(error->code == item.code);
        CHECK(error->retryable == item.retryable);
        CHECK(error->message == item.message);
        CHECK_THAT(error->said, Catch::Matchers::ContainsSubstring("answered HTTP " + std::to_string(item.status)));
        CHECK_FALSE(r.agent->busy());
    }
    // Inside the reply: OpenRouter's failed response names the kind in
    // error_type, OpenAI's error event in its code.
    SECTION("OpenRouter overloaded inside the reply")
    {
        Responses r("openrouter");
        r.fake->data(sse(kCreated) + sse(json{{"type", "response.failed"}, {"response", json{
            {"id", "resp_1"}, {"status", "failed"}, {"error", json{{"code", "server_error"}, {"message", "Provider returned error: overloaded"}}},
            {"error_type", "provider_overloaded"}}}}));
        const auto error = r.failure();
        REQUIRE(error);
        CHECK(error->code == "provider_unavailable");
        CHECK(error->message == "OpenRouter says: “Provider returned error: overloaded”");
    }
    SECTION("OpenRouter's moderation inside the reply")
    {
        Responses r("openrouter");
        r.fake->data(sse(kCreated) + sse(json{{"type", "response.failed"}, {"response", json{
            {"id", "resp_1"}, {"status", "failed"}, {"error", json{{"code", "server_error"}, {"message", "Input flagged for violence"}}},
            {"error_type", "content_policy_violation"}}}}));
        const auto error = r.failure();
        REQUIRE(error);
        CHECK(error->code == "provider_refused");
        CHECK(error->message == "OpenRouter says: “Input flagged for violence”");
    }
    SECTION("OpenAI overloaded inside the reply")
    {
        Responses r("openai");
        r.fake->data(sse(kCreated) + sse(json{{"type", "error"}, {"code", "server_is_overloaded"}, {"message", "Overloaded"}, {"param", nullptr}}));
        const auto error = r.failure();
        REQUIRE(error);
        CHECK(error->code == "provider_unavailable");
        CHECK(error->message == "OpenAI says: “Overloaded”");
    }
}

TEST_CASE("an answer whose cause cannot be told from what the service said is still unexpected", "[agent][openai][errors]")
{
    SECTION("a failed response for a picture")
    {
        Responses r("openai");
        r.fake->data(sse(kCreated) + sse(json{{"type", "response.failed"}, {"response", json{
            {"error", json{{"code", "invalid_image_format"}, {"message", "Invalid image format."}}}}}}));
        CHECK_THROWS_WITH(r.failure(), Catch::Matchers::ContainsSubstring("invalid_image_format"));
    }
    SECTION("OpenRouter's upstream error it maps to no kind")
    {
        Responses r("openrouter");
        r.fake->refuse(500, R"({"error":{"code":500,"message":"Internal Server Error","metadata":{"error_type":"unmapped"}}})");
        CHECK_THROWS_WITH(r.failure(), Catch::Matchers::ContainsSubstring("unmapped"));
    }
    SECTION("Anthropic's 404 for a model id the app sent")
    {
        Responses r("anthropic");
        r.fake->refuse(404, R"({"type":"error","error":{"type":"not_found_error","message":"model: claude-x"},"request_id":"req_1"})");
        CHECK_THROWS_WITH(r.failure(), Catch::Matchers::ContainsSubstring("not_found_error"));
    }
    SECTION("the gateway's unexpected answer")
    {
        Responses r("jusprin");
        r.fake->data(sse(kCreated) + sse(json{{"type", "error"}, {"code", "server_error"}, {"message", "Something went wrong on our side"}}));
        CHECK_THROWS_WITH(r.failure(), Catch::Matchers::ContainsSubstring("server_error"));
    }
}

