void UpdateCheck::check_now()
{
    if (m_checking || is_running_in_msix())
        return;
    m_checking = true;
    notify();

    const std::string feed = config().get(kFeedUrlKey);
    // Nothing about the person goes with the request: no install ID and no
    // system details, only what any web request carries.
    // GitHub is the service we chose for the release list, and we can change
    // it, so any answer of GitHub's other than a list the app reads is ours
    // (AGENTS.md, Error handling): a rate limit, a 404. GitHub names every
    // answer with x-github-request-id. No answer, or one without that name,
    // such as a Wi-Fi sign-in page (Http checks no certificate by default),
    // means GitHub could not be reached from the person's network.
    auto headers = std::make_shared<std::string>();
    Http::get(feed.empty() ? kReleasesUrl : feed)
        .header("Accept", "application/vnd.github+json")
        .header("User-Agent", user_agent())
        .timeout_connect(5)
        .timeout_max(10)
        .on_header_callback([headers](std::string so_far) { *headers = std::move(so_far); })
        .on_complete([this, headers](std::string body, unsigned status) {
            wxGetApp().CallAfter(reported("checking for a new version", [this, headers, body = std::move(body), status] {
                const std::string request = github_request_id(*headers);
                if (request.empty()) {
                    BOOST_LOG_TRIVIAL(warning) << "JusPrin's update check got HTTP " << status << " from something other than GitHub: " << body.substr(0, 500);
                    finish(now(), std::nullopt);
                    return;
                }
                if (status != 200)
                    fail_ours(now(), "GitHub's release list answered HTTP " + std::to_string(status) + " (request " + request + "): " + body);
                finish(now(), body, request);
            }));
        })
        .on_error([this, headers](std::string body, std::string error, unsigned status) {
            BOOST_LOG_TRIVIAL(warning) << "JusPrin's update check failed: HTTP " << status << ", " << error << ", " << body;
            wxGetApp().CallAfter(reported("checking for a new version", [this, headers, body = std::move(body), status] {
                if (const std::string request = github_request_id(*headers); status != 0 && !request.empty())
                    fail_ours(now(), "GitHub's release list answered HTTP " + std::to_string(status) + " (request " + request + "): " + body);
                finish(now(), std::nullopt);
            }));
        })
        .perform();
}

void UpdateCheck::finish(std::time_t at, const std::optional<std::string>& body, const std::string& request)
{
    m_checking = false;
    if (!body) {
        save_failure(config(), at, false);
        notify();
        return;
    }
    std::optional<Release> newer;
    try {
        newer = newer_release(*body, kVersion);
    } catch (const FeedError& error) {
        fail_ours(at, "GitHub's release list (request " + request + ") could not be read: " + error.what() + ": " + body->substr(0, 2000));
    }
    BOOST_LOG_TRIVIAL(info) << "JusPrin's update check: " << (newer ? "found " + newer->version : std::string("up to date"));
    save_success(config(), at, newer);
    notify();
}

