// The profiles ship with the app, so options that cannot be read are ours:
// the failure goes up to the timer's report, and the form is not finished.
TEST_CASE("a printer's options that cannot be read are ours, and nothing is added", "[printer-conversation]")
{
    FakeBackend    backend;
    RecordingPanel panel;
    PrinterConversation conversation(backend, panel);
    backend.options_failure = "The printer profiles could not be read: broken";
    conversation.start(ConversationMode::Add);
    action(conversation, json{{"action", "manual_setup"}});
    action(conversation, json{{"action", "form_options"}, {"catalogId", "BBL/Bambu Lab A1 mini"}, {"nozzle", 0.4}});
    bool thrown = false;
    for (int i = 0; i < 500 && !thrown && form_of(conversation).at("loading").get<bool>(); ++i) {
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        try {
            conversation.tick(std::chrono::steady_clock::now());
        } catch (const std::runtime_error& error) {
            thrown = std::string(error.what()) == backend.options_failure;
        }
    }
    CHECK(thrown);
    CHECK_FALSE(form_of(conversation).at("loading").get<bool>());
    CHECK(form_of(conversation).value("options", json()).is_null());
    CHECK(backend.added.empty());
}

