  if (!catalogId || nozzle === undefined || !options) return;
  setFinishing(true);
  onFinish({ catalogId, nozzle, ...(offersPlates ? { plate } : {}), ...(filament ? { filament } : {}),
    ...(deviceId ? { deviceId } : {}), ...(create ? { create: true } : {}) });
};

