def _delete_account(user):
    """Ends the plan the account pays for now rather than at the end of its
    term, then deletes the account, and with it its credits, tokens and kept
    chats (jusprin.apps). A JusPrin 2 account is a user of its own, apart from
    the same person's Obico account (lib/syndicate.py), which stays. If
    Chargebee can't be reached, nothing is deleted."""
    plan = JusPrinPlan.objects.filter(user=user).first()
    if plan and plan.external_id:
        billing.end_plan_now(plan)
    user.delete()


@csrf_exempt
@require_POST
def cb_webhook(request):
    """Chargebee's webhook for JusPrin 2's own site. The post is trusted only
    for the event's id: the event is read back from that site, so a forged
    post changes nothing."""
    try:
        event_id = json.loads(request.body).get('id')
    except (ValueError, AttributeError):
        event_id = None
    cb_event = billing.retrieve_event(event_id) if isinstance(event_id, str) and event_id else None
    if cb_event is None:
        LOGGER.warning('Chargebee webhook post for %r: JusPrin 2\'s site has no event by that id', event_id)
        return HttpResponse(status=400)
    billing.handle_event(cb_event)

