@require_GET
def web_done(request):
    return render(request, 'jusprin/v2/sign_in_result.html', {
        'heading': _("You're all set"),
        'line': _('You can close this tab and go back to JusPrin.'),
    })


def _refuse(code: str, status: int) -> HttpResponse:
    return HttpResponse(error_body(code), status=status, content_type='application/json')


def _decodable(photo) -> bool:
    try:
        with Image.open(photo) as image:
            image.verify()
        return True
    except (UnidentifiedImageError, SyntaxError, Image.DecompressionBombError):
        return False
    except OSError as error:
        # Pillow's own errors for a damaged image carry no errno; one that
        # does is the system failing to read the upload, which is ours.
        if error.errno is not None:
            raise
        return False
    finally:
        photo.seek(0)


def _store_photos(user, gcode_hash: str, photos) -> list:
    stamp = str(timezone.now().timestamp())
    urls = []
    for index, photo in enumerate(photos):
        path = f'print_reports/{user.id}/{gcode_hash}/{stamp}_{index}'
        _name, url = save_file_obj(path, photo, settings.TIMELAPSE_CONTAINER, user.syndicate.name, long_term_storage=True)
        urls.append(url)
