// The entry after the reprint, then the two ways Print again is withheld:
// a kept file that no longer hashes as kept, and a copy that is gone.
void print_history_refused_states(const Agent::KeptPackage& package)
{
    installed_shell()->home_view()->refresh();
    read_page(home_page(), "reprinted", "document.body.textContent.split('Sent to').length - 1 >= 3", kHistoryRead,
              "print_history_reprint_drawn", [self = shared_from_this(), package](const nlohmann::json&) {
        self->capture_history("print-again-recorded");
        // A byte added to the kept package: it is never sent, and the entry says why.
        std::ofstream(package.package, std::ios::app | std::ios::binary) << ' ';
        installed_shell()->home_view()->refresh();
        self->read_page(self->home_page(), "changed", "document.body.textContent.indexOf('Kept file changed on disk') >= 0",
                        "!Array.prototype.some.call(document.querySelectorAll('button'), function (b) { return b.textContent === 'Print again'; })",
                        "print_history_changed_package_drawn", [self](const nlohmann::json& withheld) {
            self->check(withheld == true, "print_history_changed_package_is_not_offered");
            self->capture_history("print-again-kept-file-changed");
            // The G-code's copy pruned: slice again.
            const std::string copy = Agent::kept_gcode_copy(self->persistence().jusprin_data_dir(),
                                                            self->print_history_records().at(0).hash);
            fs::remove(fs::path(copy));
            installed_shell()->home_view()->refresh();
            self->read_page(self->home_page(), "gone", "document.body.textContent.indexOf('This G-code is no longer kept') >= 0",
                            "!Array.prototype.some.call(document.querySelectorAll('button'), function (b) {"
                            " return b.textContent === 'Print again' || b.textContent === 'Export\\u2026'; })",
                            "print_history_pruned_copy_drawn", [self](const nlohmann::json& withheld) {
                self->check(withheld == true, "print_history_pruned_copy_is_not_offered");
                self->capture_history("print-again-not-kept");
                const fs::path earlier(self->m_print_history_export);
                for (const fs::path& file : {earlier, fs::path(self->m_print_history_copy),
                                             earlier.parent_path() / (earlier.stem().string() + " (2)" + earlier.extension().string())})
                    fs::remove(file);
                self->print_history_unreadable_projects();
            });
        });
    });
}

// The projects folder cannot be read while Print history is open: the
// screen says what Home's gallery says, rather than the list as it was
// read before, and the list comes back by itself once the folder can be
// read again, with nothing pressed. A folder that cannot be read is a
// state the screen says, not an unexpected error for the person to report.
void print_history_unreadable_projects()
{
    const std::string sentence = _L("Your projects couldn't be loaded. JusPrin will keep trying.").ToUTF8().data();
    const int reported_before = unexpected_errors_logged();
    auto folder = std::make_shared<UnavailableFolder>(std::filesystem::path(data_dir()) / "jusprin" / "projects");
    installed_shell()->home_view()->refresh();
    static constexpr const char* kRead =
        "{ entries: document.querySelectorAll('.history-entry').length,"
        "  problem: (document.querySelector('.history-problem') || {}).textContent || '',"
        "  text: (document.querySelector('.history-list, main') || document.body).textContent.slice(0, 400) }";
    read_page(home_page(), "unreadable", "document.querySelector('.history-problem')", kRead,
              "print_history_unreadable_drawn",
              [self = shared_from_this(), folder, sentence, reported_before](const nlohmann::json& shown) mutable {
        std::cerr << "HARNESS NOTE print_history_unreadable " << shown.dump() << '\n';
        self->capture_history("print-history-projects-unreadable");
        // The system's refusal follows, in its words: the folder is the person's to fix.
        const std::string said  = Slic3r::GUI::JusPrin::said_by(Slic3r::GUI::JusPrin::system_name(), "");
        const std::string frame = said.substr(0, said.find("“") + std::string("“").size());
        const std::string problem = shown.value("problem", "");
        self->check(shown.value("entries", -1) == 0 && problem.rfind(sentence, 0) == 0,
                    "print_history_says_the_projects_could_not_be_loaded");
        self->check(problem.find(frame) != std::string::npos, "print_history_unreadable_projects_say_the_systems_words");
        // Readable again; nothing nudges the page.
        folder.reset();
        self->read_page(self->home_page(), "readable", "document.querySelectorAll('.history-entry').length > 0", kRead,
                        "print_history_readable_again_drawn", [self, reported_before](const nlohmann::json& back) {
            std::cerr << "HARNESS NOTE print_history_readable_again " << back.dump() << '\n';
            self->check(back.value("entries", 0) > 0 && back.value("problem", "x").empty(),
                        "print_history_lists_again_by_itself");
            self->check(unexpected_errors_logged() == reported_before, "print_history_unreadable_projects_report_no_unexpected_error");

