        check(export_refused, "unavailable_storage_export_keeps_the_systems_refusal");
        const std::string new_chat = nlohmann::json{{"protocol", Agent::Protocol::kName}, {"version", Agent::Protocol::kVersion},
                                                    {"id", "unavailable-new-chat"}, {"type", "create_conversation"},
                                                    {"payload", nlohmann::json::object()}}.dump();
        run_in_chat("window.wx.postMessage(" + nlohmann::json(new_chat).dump() + ")");
        // Long enough for several of autosave's 2 s retries.
        const auto until = std::chrono::steady_clock::now() + std::chrono::seconds(8);
        auto saved_while_unavailable = std::make_shared<bool>(false);
        const int reported_before = unexpected_errors_logged();
        wait_until([until] { return std::chrono::steady_clock::now() >= until; }, "unavailable_storage_retry_window",
                   [self = shared_from_this(), autosave, folder, saved, saved_head, saved_while_unavailable, ids, reported_before,
                    deliberate_reports_before, seen]() mutable {
            self->check(!*saved_while_unavailable && autosave->state() == Workspace::ProjectAutosave::State::Failed &&
                            autosave->current_version() == saved_head,
                        "unavailable_storage_edit_stays_unsaved_and_reported");
            self->check(installed_shell()->status_row()->project_summary().BeforeFirst('\n').EndsWith(
                            wxGetTranslation("Couldn't save")),
                        "unavailable_storage_has_plain_status_text");
            // A folder the person cannot write is theirs to fix: the system's
            // words reach them, and nothing reaches us.
            const std::string system_said = autosave->system_said();
            self->check(!autosave->failed_on_our_side() && system_said.rfind(Slic3r::GUI::JusPrin::system_name(), 0) == 0 &&
                            system_said.find("“") != std::string::npos,
                        "unavailable_storage_keeps_the_systems_words");
