// The app ended in the middle of a chat restore. Both versions it moved
// between were pinned and every version is committed, so nothing is lost;
// what is left is to make the open chat match the model. If the model had
// already moved to the chat's version, the chat is made active, as the
// restore would have done; if not, the project stays as it was before the
// restore. Either way the restore was cut short, which we must hear about.
void ProjectAutosave::finish_interrupted_chat_restore()
{
    const auto interrupted = m_store->interrupted_chat_restore();
    if (!interrupted)
        return;
    const bool model_moved = m_store->head_id() != interrupted->from_version;
    const bool chat_moved  = m_persistence.document().active_conversation_id() == interrupted->conversation_id;
    if (model_moved && !chat_moved) {
        m_persistence.record_chat_restore(m_persistence.document().dump(), interrupted->from_version,
                                          interrupted->to_version, interrupted->conversation_id);
        if (!persist_document(true))
            throw_failure();
        m_persistence.notify_chat_restore_published();
    }
    m_store->finish_chat_restore();
    const char* finished = !model_moved ? "nothing had moved, so the project was left as it was before the restore" :
                           chat_moved   ? "it had finished but for its marker" :
                                          "the model had moved, so its chat was made active";
    m_interrupted_restore = std::make_exception_ptr(std::runtime_error(
        "a chat restore was interrupted in project " + m_store->project_id() + " (from version " +
        interrupted->from_version + " to " + interrupted->to_version + " for chat " + interrupted->conversation_id +
        "); " + finished));
}
