// The same save refused by the system for a cause the person can fix, before
// the change or after it: the model hears the system's words, to tell the
// person, and nothing is reported.
TEST_CASE("a tool call whose save the system refuses is not reported", "[agent][provider][tools]")
{
    auto provider = std::make_unique<ToolCallingAgent>();
    ToolCallingAgent* scripted = provider.get();
    Harness harness(std::move(provider));
    int reported = 0;
    harness.host.set_unexpected_error_handler([&reported](const std::string&, std::exception_ptr) { ++reported; });
    harness.handshake();
    const auto refuse = [] {
        throw std::filesystem::filesystem_error("cannot create current-state.pending",
                                                std::make_error_code(std::errc::no_space_on_device));
    };
    const bool before = GENERATE(true, false);
    CAPTURE(before);
    harness.host.tools().set_version_callbacks(
        [&](const ToolActivity&) { if (before) refuse(); return std::string("v-before"); },
        [&](const ToolActivity&, const std::string&) { refuse(); });
    REQUIRE(harness.workspace.select_object(harness.workspace.snapshot().plates[0].objects[0].id).succeeded());
    harness.send_user_message("duplicate it", "refused-c-1");
    for (int i = 0; i < 20 && !scripted->continuation; ++i) {
        harness.host.pump_stream();
        harness.host.pump_tools();
    }
    REQUIRE(scripted->continuation);
    CHECK(scripted->continuation->state == "failed");
    const json sent = json::parse(scripted->continuation->output_json);
    CHECK(sent["error"]["code"] == "local_save_failed");
    CHECK(sent["error"]["message"].get<std::string>().find(std::make_error_code(std::errc::no_space_on_device).message()) !=
          std::string::npos);
    CHECK(reported == 0);
}

