// Runs `work`, which reads or writes the person's own work in `folder`. The
// system refusing it, for any reason, leaves as a SystemRefusal; any other
// failure leaves unchanged.
template<class Work> decltype(auto) persons_storage(const std::filesystem::path& folder, Work&& work)
{
    try {
        return std::forward<Work>(work)();
    } catch (const std::exception& error) {
        std::optional<SystemRefusal> refusal = as_refusal(error, folder);
        if (!refusal)
            throw;
        throw *refusal;
    }
}

// The system's reason for a write into `folder` that a writer reported only
// as failed, as OrcaSlicer's writers do: the same folder, asked now for a
// small file, refuses it again, and the call that fails gives the reason.
// Nothing when the folder takes the file: the system did not refuse, and the
// failure is ours.
inline std::optional<SystemRefusal> folder_refusal(const std::filesystem::path& folder, const std::string& what)
{
    const std::filesystem::path probe = folder / ".jusprin-write-check";
    const std::error_code refused = write_file_atomically(probe.u8string(), std::string("{}"));
    std::error_code ignored;
    std::filesystem::remove(probe, ignored);
    if (!refused)
        return std::nullopt;
    return SystemRefusal(refused, folder, what);
}

// The system's words, after the folder, when the failure is its refusal of
// the person's storage; nothing otherwise.
inline std::optional<std::string> refused_by_system(const std::exception& error)
{
    if (const auto* refusal = dynamic_cast<const SystemRefusal*>(&error))
        return refusal->words();
    return std::nullopt;
}

