// What the person is told where an unexpected failure stopped their request,
// beside the report.
// Retryable: an outage or a passing failure lands here too, and a person
// should not have to type the message again.
AgentError unexpected_error() { return {"unexpected_error", translated(L("Something went wrong on our side")), true}; }

// A turn keeps the pictures it sends in the project folder as it sends them.
// When the system refuses that write for a cause the person can fix (a full
// disk, a folder they cannot write), the turn fails in the system's words and
// can be tried again once they fix it. Nothing for any other failure.
std::optional<AgentError> refused_keeping(const std::exception& error)
{
    const std::optional<std::string> words = refused_by_system(error);
    if (!words)
        return std::nullopt;
    BOOST_LOG_TRIVIAL(warning) << "A chat turn could not keep what it sends: " << error.what();
    return AgentError{"storage_refused", said_by(system_name(), *words), true};
}

