record.state         = "staged";
const AttachmentClassification classification = classify_attachment(record.original_name, "");
record.kind        = classification.kind;
record.mime        = classification.mime;

// A file the person chose that the system will not let the app read, for
// any reason (one only another user may open, one moved since it was
// picked), fails on its chip in the system's words. Any other failure is
// ours, and goes up.
std::string bytes;
try {
    const std::uintmax_t size = persons_storage(file.parent_path(), [&] { return std::filesystem::file_size(file); });
    if (size > kMaxAttachmentBytes) {
        // Refused by its size alone, without reading it.
        record.state = "error";
        record.error = AgentError{"too_large", translated(L("This file is too large to attach."))};
    } else {
        persons_storage(file.parent_path(), [&] {
            std::ifstream in(file, std::ios::binary);
            if (!in)
                throw std::filesystem::filesystem_error("cannot open the attachment", file, std::error_code(errno, std::generic_category()));
            bytes.assign(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
            if (in.bad())
                throw std::filesystem::filesystem_error("cannot read the attachment", file, std::error_code(errno, std::generic_category()));
        });
    }
} catch (const std::exception& error) {
    const std::optional<std::string> words = refused_by_system(error);
    if (!words)
        throw;
    BOOST_LOG_TRIVIAL(warning) << "JusPrin could not read the attachment " << file.u8string() << ": " << error.what();
    record.state = "error";
    record.error = AgentError{"unreadable", said_by(system_name(), *words)};
}
if (record.state == "error") {
    m_persistence.document().add_attachment(record, m_persistence.timestamp());
    m_persistence.commit();
    m_persistence.flush();
    send_attachment_updated(record, correlation_id);
    return;
}

// The model filter is the classifier's own list, so nothing it offers is
// a file the Agent cannot read.
answer = {};
h.deliver("pick_attachment", json{{"kind", "model"}});
for (const char* extension : {"stl", "3mf", "step", "obj"})
    CHECK(std::count(requests.back().extensions.begin(), requests.back().extensions.end(), extension) == 1);

