    {
        auto*      autosave = installed_shell()->autosave();
        LeftPane*  pane     = installed_shell()->left_pane();
        AppMenus*  menus    = installed_shell()->app_menus();
        const auto versions = autosave->history();
        const int  before   = unexpected_errors_logged();
        auto       seen     = std::make_shared<SeenDialogs>();
        pane->set_export_chooser([path = (fs::path(data_dir()) / "after-fault.3mf").string()] { return path; });
        wxMenu*     exports = labelled(menus->file_menu(), _L("Export"))->GetSubMenu();
        wxMenuItem* project = labelled(exports, _L("Project 3MF…"));
        check(project != nullptr, "autosave_fault_export_menu_item");
        if (project != nullptr)
            exports->QueueEvent(new wxCommandEvent(wxEVT_MENU, project->GetId()));
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(30);
        wait_until([before, deadline] { return unexpected_errors_logged() >= before + 1 || std::chrono::steady_clock::now() > deadline; },
                   "autosave_fault_export_from_the_menu",
                   [self = shared_from_this(), pane, menus, versions, before, seen, then, deadline] {
            pane->set_export_chooser({});
            self->check(unexpected_errors_logged() == before + 1, "autosave_fault_export_from_the_menu_is_reported");
            // Open recent lists the projects when File opens. The one listed
            // is the open project, which is saved before it is opened.
            menus->file_menu()->QueueEvent(new wxMenuEvent(wxEVT_MENU_OPEN, 0, menus->file_menu()));
            self->wait_until([menus, deadline] {
                                 return menus->open_recent_menu()->GetMenuItemCount() > 0 || std::chrono::steady_clock::now() > deadline;
                             },
                             "autosave_fault_open_recent_listed",
                             [self, pane, menus, versions, before, seen, then, deadline] {
                self->check(menus->open_recent_menu()->GetMenuItemCount() > 0, "autosave_fault_open_recent_lists_the_project");
                if (menus->open_recent_menu()->GetMenuItemCount() > 0)
                    menus->open_recent_menu()->QueueEvent(
                        new wxCommandEvent(wxEVT_MENU, menus->open_recent_menu()->FindItemByPosition(0)->GetId()));
                self->wait_until([before, deadline] {
                                     return unexpected_errors_logged() >= before + 2 || std::chrono::steady_clock::now() > deadline;
                                 },
                                 "autosave_fault_open_recent", [self, pane, versions, before, seen, then] {
                    self->check(unexpected_errors_logged() == before + 2, "autosave_fault_open_recent_is_reported");
                    // The Restore button is drawn on the pane, whose click
                    // handler reports ("using the plates pane").
                    self->check(!versions.empty(), "autosave_fault_has_a_version_to_restore");
                    pane->set_restore_confirmation([] { return true; });
                    if (!versions.empty())
                        reported("using the plates pane", [pane, id = versions.back().id] { pane->restore_version(id); })();
                    pane->set_restore_confirmation({});
                    // Each report opens its dialog a moment after it is logged.
                    self->print_history_wait([before, seen] { return unexpected_errors_logged() >= before + 3 && seen->shown.size() >= 3; },
                                             "autosave_fault_deliberate_saves_answered", [self, seen, before, then] {
                        const auto titled = [seen](const wxString& title) {
                            const std::string start = std::string(title.ToUTF8()) + " |";
                            return std::any_of(seen->shown.begin(), seen->shown.end(),
                                               [&](const std::string& shown) { return shown.rfind(start, 0) == 0; });
                        };
                        self->check(unexpected_errors_logged() == before + 3, "autosave_fault_export_restore_open_are_reported");
                        self->check(!titled(wxGetTranslation("Export failed")) && !titled(wxGetTranslation("Restore failed")) &&
                                        !titled(wxGetTranslation("Couldn't open project")),
                                    "autosave_fault_export_restore_open_do_not_say_try_again");
                        seen->Unregister();
                        then();
                    });
                });
            });
        });
    }

