    void verify_autosave_fault_after_cleanup()
    {
        auto* autosave = installed_shell()->autosave();
        const fs::path project = fs::path(data_dir()) / "jusprin" / "projects" / persistence().document().project_id();
        const fs::path kept = fs::path(data_dir()) / "harness-kept-resources";
        fs::remove_all(kept);
        fs::rename(project / "resources", kept);
        fs::create_directories(project / "resources");
        const int reported_before = unexpected_errors_logged();
        // The report dialog, which the person answers.
        auto dialogs = std::make_shared<ShownDialogs>();
        check(m_plater->rename_object(0, "Edited before the fault"), "autosave_fault_edit_applied");
        // The report is logged and its dialog opens a moment later: wait for
        // both, or 30 s.
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(30);
        wait_until([reported_before, dialogs, deadline] {
                       return (unexpected_errors_logged() > reported_before && !dialogs->titles.empty()) ||
                              std::chrono::steady_clock::now() > deadline;
                   },
                   "autosave_fault_in_the_worker",
                   [self = shared_from_this(), autosave, reported_before, dialogs, project, kept] {
        // that cannot be written is a failed save, reported and retried.
        fail(error);
        return std::nullopt;
    }
    return id;
}

