def server_error(request):
    """The site's answer when a view fails unexpectedly (urls_ent.handler500),
    after Sentry's Django integration has reported the failure. On JusPrin 2's
    pages the person reads the one sentence for it, in the app's language; the
    endpoints the app calls answer with the gateway's error body. Every other
    path keeps Django's own page."""
    if not request.path.startswith(PATH):
        return defaults.server_error(request)
    if request.path.startswith(PAGES):
        heading = _('Something went wrong on our side')
        return render(request, 'jusprin/v2/web/message.html', {'title': heading, 'heading': heading}, status=500)
    return HttpResponse(unexpected_body(), status=500, content_type='application/json')

