// Records a failed request as the host or curl gave it.
void record_error(HostAnswer& answer, const std::string& body, const std::string& error, unsigned status)
{
    answer.passed = false;
    answer.status = status;
    answer.said   = status != 0 ? "HTTP " + std::to_string(status) + ": " + one_line(body) : one_line(error);
}

// OrcaSlicer's Moonraker and OctoPrint tests, each copied with two changes.
// The request gives up after kConnectionWait: upstream's has no upper limit
// (Http's DEFAULT_TIMEOUT_MAX is 0), so a host that accepts the connection and
// never replies would hold the test, and the chat's tool call, for good. And
// the HTTP status and the host's own words come back, where upstream returns
// a message that puts a cause on curl's error and only logs Klipper's state.
// The requests and checks are upstream's: when Moonraker::test or
// OctoPrint::test changes, change these.
class MoonrakerTest : public Moonraker
{
public:
    using Moonraker::Moonraker;

    HostAnswer answer() const
    {
        HostAnswer answer{true};
        auto       http = Http::get(make_url("server/info"));
        set_auth(http);
        http.timeout_max(kConnectionWait.count())
            .on_error([&](std::string body, std::string error, unsigned status) { record_error(answer, body, error, status); })
            .on_complete([&](std::string body, unsigned) {
                try {
                    std::stringstream           stream(body);
                    boost::property_tree::ptree tree;
                    boost::property_tree::read_json(stream, tree);
                    const auto klippy_state = tree.get_optional<std::string>("result.klippy_state");
                    if (!klippy_state) {
                        answer = {false, 0, "The host responded but it doesn't look like Moonraker (missing result.klippy_state)."};
                        return;
                    }
                    answer.said = *klippy_state;
                } catch (const std::exception& ex) {
                    answer = {false, 0, std::string("Could not parse Moonraker server response: ") + ex.what()};
                }
            })
#ifdef WIN32
            .ssl_revoke_best_effort(m_ssl_revoke_best_effort)
#endif
            .perform_sync();
        return answer;
    }
};

class OctoPrintTest : public OctoPrint
{
public:
    using OctoPrint::OctoPrint;

    HostAnswer answer() const
    {
        HostAnswer answer{true};
        auto       http = Http::get(make_url("api/version"));
        set_auth(http);
        http.timeout_max(kConnectionWait.count())
            .on_error([&](std::string body, std::string error, unsigned status) { record_error(answer, body, error, status); })
            .on_complete([&](std::string body, unsigned) {
                try {
                    std::stringstream           stream(body);
                    boost::property_tree::ptree tree;
                    boost::property_tree::read_json(stream, tree);
                    if (!tree.get_optional<std::string>("api")) {
                        answer = {false, 0, "The host responded but its answer has no OctoPrint API version."};
                        return;
                    }
                    const auto text = tree.get_optional<std::string>("text");
                    if (!validate_version_text(text))
                        answer = {false, 0, "Mismatched type of print host: " + (text ? *text : std::string(get_name()))};
                } catch (const std::exception&) {
                    answer = {false, 0, "Could not parse server response."};
                }
            })
#ifdef WIN32
            .ssl_revoke_best_effort(m_ssl_revoke_best_effort)
#endif
            .perform_sync();
        return answer;
    }
};

// Every other type runs OrcaSlicer's own test, the one its Physical Printer
// dialog's Test button runs, unchanged: copying each would be a dozen copies
// to keep in step. Its request has no upper limit, so the test runs on a
// thread of its own, and the answer is given up on after kConnectionWait.
// The thread is left to finish, and its answer is dropped: against a host
// that holds the connection open and never answers, it waits, with one
// socket, until the app quits. OrcaSlicer runs these hosts off the GUI
// thread too, in its upload queue. The status comes back only inside the
// test's message, where PrintHost::format_error puts it as "HTTP 401: ...".
HostAnswer upstream_answer(std::shared_ptr<PrintHost> host)
{
    std::packaged_task<HostAnswer()> test([host] {
        wxString   said;
        HostAnswer answer{host->test(said)};
        answer.said = one_line(said.ToUTF8().data());
        // No space after the colon: one_line drops the one an empty body
        // leaves at the end ("HTTP 401: " becomes "HTTP 401:").
        std::smatch status;
        if (!answer.passed && std::regex_search(answer.said, status, std::regex(R"(\bHTTP (\d{3}):)")))
            answer.status = static_cast<unsigned>(std::stoul(status[1].str()));
        return answer;
    });
    auto answer = test.get_future();
    std::thread(std::move(test)).detach();
    if (answer.wait_for(kConnectionWait) == std::future_status::timeout)
        return {false, 0, {}, true};
    // An exception from the test is rethrown here, and goes on to the worker.
    return answer.get();
}

// The types that go through an online service the person signs in to,
// whose PrintHost::is_cloud() is true. The chat does not connect these: they
// need that sign-in, not an address. Asking a PrintHost would construct one,
// and these constructors read their sign-in files.
bool online_service(PrintHostType type)
{
    return type == htObico || type == htSimplyPrint || type == ht3DPrinterOS;
}

// A connection type as OrcaSlicer's printer settings label it ("Elegoo
// Link"), from the name its settings file stores ("elegoolink").
std::string host_label(const std::string& type)
{
    const ConfigOptionDef* types = print_config_def.get("host_type");
    const auto             found = std::find(types->enum_values.begin(), types->enum_values.end(), type);
    return found == types->enum_values.end() ? type : types->enum_labels[found - types->enum_values.begin()];
}

