                frame({'type': 'content_block_start', 'index': 0, 'content_block': {'type': 'text', 'text': ''}}, 'content_block_start')
            while time.time() - start < seconds:
                words += 1
                if anthropic:
                    frame({'type': 'content_block_delta', 'index': 0, 'delta': {'type': 'text_delta', 'text': f'word{words} '}}, 'content_block_delta')
                else:
                    frame({'type': 'response.output_text.delta', 'delta': f'word{words} '})
                append('slow.jsonl', {'t': time.time(), 'sent': words})
