  if (!printer) return;
  const hook = setInterval(() => {
    const b = window.__jusprinBridge;
    if (!b || b.__hooked) return;
    const deliver = b.deliver.bind(b);
    b.deliver = (env) => {
      try {
        const e = typeof env === 'string' ? JSON.parse(env) : env;
        const text = JSON.stringify(e.payload || {});
        const i = text.indexOf('"form"');
        say({ t: Date.now(), got: e.type, form: i >= 0 ? text.slice(i, i + 700) : undefined });
      } catch (x) {}
      return deliver(env);
